def cat(t):
    t=t.lower()
    if "ai" in t or "artificial intelligence" in t or "الذكاء الاصطناعي" in t: return "الذكاء الاصطناعي"
    if any(x in t for x in ("jobs","work","labour","employment","skills")): return "سوق العمل"
    return "اقتصاد وأعمال"

